import React, {memo, useEffect} from 'react';
import {
  Animated,
  Dimensions,
  I18nManager,
  Image,
  StyleSheet,
  Text,
  TouchableWithoutFeedback,
  View,
  Platform,
} from 'react-native';
import Svg, {Rect, Defs, LinearGradient, Stop} from 'react-native-svg';
import {EventRegister} from './EventRegister';
import {Colors} from './utils';
import Images from './images';

const AnimatedImage = Animated.createAnimatedComponent(Image);
const {width} = Dimensions.get('window');
export const tabBarHeight = 65;

const BottomTabBar = (props) => {
  const {
    tabs,
    tabBackgroundColor = '#2B2841',
    iconTintColor = '#fff',
    activeIconTintColor = Colors.orange,
    activeBackgroundColor = '#ddd',
  } = props;
  const values = tabs.map((tab, index) => new Animated.Value(index === 0 ? 1 : 0));
  const value = React.useRef(new Animated.Value(0)).current;

  const rtlTranslateX = value.interpolate({
    inputRange: [-width, 0],
    outputRange: [width, 1],
  });

  const translateX = value.interpolate({
    inputRange: [0, width],
    outputRange: [-width, 0],
  });

  const color = '#bcbcbc',
    border = 15,
    opacity = 0.35,
    inset = false;

  const linear = (key) => {
    return [
      <Stop offset="0" stopColor={color} stopOpacity={opacity} key={key + 'Linear0'} />,
      <Stop offset="1" stopColor={color} stopOpacity="0" key={key + 'Linear1'} />,
    ];
  };

  const lineWidth = border;

  useEffect(() => {
    onPress(props.selectedTabIndex - 1);
    const tabBarIndex = EventRegister.addEventListener('setBottomBarIndex', (data) => {
      onPress(data - 1);
    });

    return () => {
      EventRegister.removeEventListener(tabBarIndex);
    };
  }, []);

  const onPress = (index) => {
    const tabWidth = width / tabs.length;
    Animated.sequence([
      Animated.parallel(
        values.map((v) =>
          Animated.timing(v, {
            toValue: 0,
            duration: 100,
            useNativeDriver: true,
          }),
        ),
      ),
      Animated.parallel([
        Animated.spring(value, {
          toValue: tabWidth * index,
          useNativeDriver: true,
        }),
        Animated.spring(values[index], {
          toValue: 1,
          useNativeDriver: true,
        }),
      ]),
    ]).start();
    props.selectedIndexCallback(index + 1);
  };

  return (
    <View style={styles.subContainer}>
      {Platform.OS == 'android' ? (
        <Svg height={lineWidth} width={width + lineWidth} style={{position: 'absolute', top: inset ? 0 : -lineWidth}}>
          <Defs>
            <LinearGradient id="top" x1="0%" x2="0%" y1="100%" y2="0%">
              {linear('BorderTop')}
            </LinearGradient>
            <LinearGradient id="top-inset" x1="0%" x2="0%" y1="0%" y2="100%">
              {linear('BorderTopInset')}
            </LinearGradient>
          </Defs>
          <Rect x={0} y={0} width={width} height={lineWidth} fill={`url(#top${inset ? '-inset' : ''})`} />
        </Svg>
      ) : null}
      <View style={[styles.container, {backgroundColor: tabBackgroundColor}]}>
        {tabs.map((tab, key) => {
          const tabWidth = width / tabs.length;
          const cursor = tabWidth * key;
          const opacity = value.interpolate({
            inputRange: [cursor - tabWidth, cursor, cursor + tabWidth],
            outputRange: [1, 0, 1],
            extrapolate: 'clamp',
          });
          const translateY = values[key].interpolate({
            inputRange: [0, 1],
            outputRange: [74, 0],
            extrapolate: 'clamp',
          });
          const opacity1 = values[key].interpolate({
            inputRange: [0, 1],
            outputRange: [0, 1],
            extrapolate: 'clamp',
          });
          return (
            <React.Fragment {...{key}}>
              <Animated.View
                style={[
                  styles.curveContainer,
                  {
                    transform: [
                      {
                        translateX: I18nManager.isRTL ? rtlTranslateX : translateX,
                      },
                    ],
                    right: I18nManager.isRTL ? null : -134,
                    left: I18nManager.isRTL ? -50 : null,
                  },
                ]}>
                <AnimatedImage
                  resizeMode={'cover'}
                  style={{width: 180, height: 70, tintColor: tabBackgroundColor}}
                  source={Images.ic_bottom}
                />
              </Animated.View>
              <TouchableWithoutFeedback onPress={() => onPress(key)}>
                <Animated.View style={[styles.tab, {opacity}]}>
                  <Image
                    source={tab.icon}
                    resizeMode={'contain'}
                    style={{width: 25, height: 25, tintColor: iconTintColor}}
                  />
                </Animated.View>
              </TouchableWithoutFeedback>
              <Animated.View
                style={{
                  position: 'absolute',
                  // top: -12,
                  // bottom: 12,
                  left: tabWidth * key,
                  width: tabWidth + 10,
                  height: 74,
                  alignItems: 'center',
                  opacity: opacity1,
                  transform: [{translateY}],
                  zIndex: 1,
                }}>
                <View style={styles.activeIcon}>
                  <View style={[styles.activeIconContainer, {backgroundColor: activeBackgroundColor}]}>
                    <Image
                      source={tab.icon}
                      resizeMode={'contain'}
                      style={{
                        width: 25,
                        height: 25,
                        tintColor: activeIconTintColor,
                        alignSelf: 'center',
                      }}
                    />
                  </View>
                  <Text style={styles.tabText}>{tab.name}</Text>
                </View>
              </Animated.View>
            </React.Fragment>
          );
        })}
      </View>
    </View>
  );
};

export default memo(BottomTabBar, (prev, next) => {
  // console.log('prev', prev);
  // console.log('next', next);
  return true;
});

const styles = StyleSheet.create({
  container: {
    flexDirection: 'row',
    shadowColor: 'gray',
    shadowOpacity: 0.6,
    shadowOffset: {width: 0, height: 2},
    shadowRadius: 10,
  },
  subContainer: {
    position: 'relative',
    width: width,
    elevation: 8,
    shadowColor: 'rgba(0,0,0,0.5)',
    shadowRadius: 5,
  },
  tab: {
    // flex: 1,
    justifyContent: 'center',
    alignItems: 'center',
    height: tabBarHeight,
    width: width / 5,
  },
  activeIcon: {
    width: 50,
    height: 50,
    justifyContent: 'center',
    alignItems: 'center',
  },
  curveContainer: {
    alignSelf: 'center',
    position: 'absolute',
    top: -60,
  },
  tabText: {
    fontSize: 10,
    paddingTop: 2,
    marginTop: 5,
    color: Colors.white,
    textAlign: 'center',
  },
  activeIconContainer: {
    width: 50,
    height: 50,
    borderRadius: 50 / 2,
    justifyContent: 'center',
    alignItems: 'center',
    alignSelf: 'center',
    backgroundColor: 'white',
  },
  shadowStyle: {
    backgroundColor: 'black',
    shadowOpacity: 1,
    width: '100%',
    height: 1,
    shadowRadius: 4,
    shadowOffset: {
      width: 0,
      height: -3,
    },
    shadowColor: '#000000',
  },
});
